{
  "implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']
    total_min = sum(seg['minimum'] for seg in segments)
    total_cap = sum(seg['capacity'] for seg in segments)
    if budget < total_min or budget > total_cap:
        raise ValueError('Budget out of bounds')
    n = len(segments)
    alloc = [seg['minimum'] for seg in segments]
    remaining = budget - sum(alloc)
    while remaining > 0:
        best_idx = -1
        best_score = -1.0
        for i, seg in enumerate(segments):
            if alloc[i] >= seg['capacity']:
                continue
            score = seg['importance'] / (alloc[i] + 1)
            if score > best_score:
                best_score = score
                best_idx = i
        if best_idx == -1:
            break
        alloc[best_idx] += 1
        remaining -= 1
    total = sum(alloc)
    by_name = {segments[i]['name']: alloc[i] for i in range(n)}
    return {
        'allocations': alloc,
        'by_name': by_name,
        'total': total
    }"
}
